const range = {
  from: 1,
  to: 3,
  [Symbol.iterator]() {
    let current = this.from;
    const last = this.to;
    return {
      next() {
        return current <= last ? {value: current++, done: false} : {done: true};
      }
    };
  }
};
console.log([...range]);
